(()=>{'use strict';const {Battle,CARDS,ROLES}=PartyV3,$=id=>document.getElementById(id);let battle,selected=null,executor=null,busy=false,token=0;const STORE='sumyeon-party-v3-energy-v1';
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function save(){try{localStorage.setItem(STORE,JSON.stringify(battle.snapshot()))}catch{}}
 function notice(text){$('notice').textContent=text}
 function health(a){return `<span class="health">${a.hp}/${a.max}${a.shield?' · 보호 '+a.shield:''}${a.weak?' · 약화 '+a.weak:''}</span><span class="hpbar"><i style="width:${a.hp/a.max*100}%"></i></span>`}
 function intentText(a){const i=battle.s.intents.find(i=>i.actor===a.id);if(a.hp<=0)return '격파';if(!i)return '';if(i.type==='prepare')return `준비 · 다음 ${i.nextTarget?battle.actor(i.nextTarget).name:'전체'} · 피해 ${Math.max(0,(i.nextDamage??5)-a.weak)}`;const damage=Math.max(0,i.damage-a.weak);return i.type==='area'?`→ 전체 · 피해 ${damage}`:`→ ${battle.actor(i.target).name} · 피해 ${damage}`}
 function threatText(a){if(a.hp<=0)return '';const attacks=battle.s.intents.filter(i=>battle.actor(i.actor).hp>0&&(i.type==='area'||i.type==='attack'&&i.target===a.id));if(!attacks.length)return '';const total=attacks.reduce((n,i)=>n+Math.max(0,i.damage-battle.actor(i.actor).weak),0);return `받을 공격 ${total} · 보호 후 ${Math.max(0,total-a.shield)}`}
 function bonusText(a){if(selected==='basic')return '고유 효과 없음';if(!a.ready)return '이번 라운드 사용함';if(a.id==='anchor')return '자신 보호 +4';if(a.id==='recall')return '다음 손패에 보관';if(a.id==='care'){const lowest=battle.s.allies.filter(x=>x.hp>0).reduce((best,x)=>!best||x.hp/x.max<best.hp/best.max?x:best,null);return `${lowest.name} 보호 +4`}const memory=battle.s.memory;return memory&&memory.actor!==a.id&&battle.actor(memory.target).hp>0?`${battle.actor(memory.target).name} 추격 4`:'추격 대상 없음'}
 function previewText(target){if(!selected||!executor)return '';try{const s=battle.preview(selected,executor,target),changes=[];[...s.allies,...s.enemies].forEach(a=>{const old=battle.actor(a.id);if(a.hp!==old.hp)changes.push(`${a.name} −${old.hp-a.hp}${a.hp===0?' · 행동 취소':''}`);if(a.shield>old.shield)changes.push(`${a.name} 보호 +${a.shield-old.shield}`);if(a.weak>old.weak)changes.push('다음 공격 −4')});if(s.zones.reserve.includes(selected))changes.push('다음 손패 보관');if(battle.definition(selected).draw)changes.push(`${s.zones.hand.length-battle.s.zones.hand.length+1}장 뽑기`);return changes.join(' · ')||'고유 효과 없음'}catch{return ''}}
 function render(){const s=battle.s,c=battle.definition(selected),targetSide=executor?c?.target:null;const lock=busy||s.status!=='playing';$('round').textContent=`라운드 ${s.round}`;$('energy').textContent=`◈ ${s.energy} / ${s.energyMode==='bank'?5:4}`;$('energy-mode').value=s.energyMode||'reset';$('next-energy').textContent=s.energyMode==='bank'?`다음 ${Math.min(5,s.energy+2)} · 회복 +2`:'다음 4';$('selection').textContent=!selected?'카드 선택':!executor?`${c.name} · 실행자 선택`:`${c.name} · ${battle.actor(executor).name} → 대상 선택`;$('cancel').hidden=!selected;$('cancel').disabled=busy;$('end').disabled=lock;$('basic').disabled=lock||s.energy<1;$('basic').classList.toggle('selected',selected==='basic');$('scenario').value=s.mode;$('fixture-note').hidden=!s.mode.startsWith('pressure-');
 $('enemies').innerHTML=s.enemies.map(a=>`<button class="enemy ${a.hp<=0?'dead':''} ${targetSide==='enemy'&&a.hp>0?'targetable':''}" data-unit="${a.id}" aria-label="${a.name}, HP ${a.hp}, ${intentText(a)}" ${lock||!executor||targetSide!=='enemy'||a.hp<=0?'disabled':''}><span class="name">${a.name}</span>${health(a)}<span class="intent">${intentText(a)}</span>${targetSide==='enemy'&&a.hp>0?`<span class="preview">${esc(previewText(a.id))}</span>`:''}</button>`).join('');
 $('allies').innerHTML=s.allies.map(a=>`<button class="ally ${a.hp<=0?'dead':''} ${executor===a.id?'selected':''} ${targetSide==='ally'&&a.hp>0?'targetable':''}" style="--color:${a.color}" data-unit="${a.id}" aria-label="${a.name}, HP ${a.hp}, ${a.ready?'고유 효과 준비':'고유 효과 사용함'}" ${lock||!selected||a.hp<=0||executor&&targetSide!=='ally'?'disabled':''}><span class="name">${a.name}<span aria-hidden="true" class="ready ${a.ready?'':'spent'}">◆</span></span>${health(a)}${threatText(a)?`<span class="threat">${esc(threatText(a))}</span>`:''}${selected?`<span class="bonus">${esc(bonusText(a))}</span>`:''}${targetSide==='ally'&&a.hp>0?`<span class="preview">${esc(previewText(a.id))}</span>`:''}</button>`).join('');
 $('hand').innerHTML=s.zones.hand.map(id=>{const d=battle.definition(id);return `<button class="card ${selected===id?'selected':''}" data-card="${id}" aria-label="${d.name}, 비용 ${d.cost}, ${d.text}" ${lock||s.energy<d.cost?'disabled':''}><span class="cost">${d.cost}</span><span class="icon" aria-hidden="true">${d.icon}</span><strong>${d.name}</strong><span class="text">${d.text}</span></button>`}).join('');$('deck').textContent=`뽑기 ${s.zones.draw.length} · 버림 ${s.zones.discard.length} · 공용 덱 ${Object.keys(s.cards).length}`;$('reserved').textContent=s.zones.reserve.length?'보관: '+s.zones.reserve.map(id=>battle.definition(id).name).join(', '):'';PartyV3Stage.set(s);
 if(s.status!=='playing'&&!busy&&!$('result').open){$('result-title').textContent=s.status==='won'?'전투 승리':'전투 패배';$('result-text').textContent=`${s.round}라운드 · 생존 ${s.allies.filter(a=>a.hp>0).length}/4`;$('result').showModal()}}
 function start(mode,energyMode=$('energy-mode').value){token++;busy=false;selected=executor=null;if($('result').open)$('result').close();battle=new Battle(mode,20261009,energyMode);notice('');save();render()}
 function select(id){if(busy)return;selected=id;executor=null;notice('');render()}
 async function animate(actor,events){const turn=++token,ms=Number($('speed').value)===0?0:420/Number($('speed').value);busy=true;PartyV3Stage.animate(actor,ms);render();if(ms)events.forEach(e=>document.querySelector(`[data-unit="${e.target}"]`)?.classList.add('flash'));if(ms)await new Promise(r=>setTimeout(r,ms));if(turn!==token)return;busy=false;render()}
 function unit(id){if(busy||!selected)return;const a=battle.actor(id);if(!executor){if(!battle.s.allies.includes(a)||a.hp<=0)return;executor=id;render();return}try{const actor=executor,events=battle.play(selected,actor,id);selected=executor=null;save();animate(actor,events)}catch(e){notice(e.message)}}
 $('hand').addEventListener('click',e=>{const b=e.target.closest('[data-card]');if(b&&!b.disabled)select(b.dataset.card)});['allies','enemies'].forEach(id=>$(id).addEventListener('click',e=>{const b=e.target.closest('[data-unit]');if(b&&!b.disabled)unit(b.dataset.unit)}));$('basic').onclick=()=>select('basic');$('cancel').onclick=()=>{selected=executor=null;render()};$('end').onclick=()=>{if(busy)return;selected=executor=null;const events=battle.endRound();save();animate(null,events)};$('energy-mode').onchange=()=>start(battle.s.mode,$('energy-mode').value);$('scenario').onchange=()=>start($('scenario').value);$('restart').onclick=()=>start(battle.s.mode);$('retry').onclick=()=>start(battle.s.mode);$('help').onclick=()=>$('rules').showModal();$('abilities').innerHTML=ROLES.map(r=>`<p><strong>${r.name}</strong> · ${r.ability}</p>`).join('');document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('rules').open&&!$('result').open){selected=executor=null;render()}});
 try{const saved=JSON.parse(localStorage.getItem(STORE));battle=saved?Battle.restore(saved):new Battle('normal',20261009,'bank')}catch{battle=new Battle('normal',20261009,'bank')}render();
})();
